"""Unit 23: Tagalog Basic Course, Semester I, Chapter 7, Lesson 1: Sports.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (piloting edition, September 2017).
Pictures, audio, partner work and role plays are left out; the book's answer keys are used (misprints noted),
amounts are written in words in the spoken lines and with symbols in the English notes."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


# ------------------------------------------------------------------ 1 expressions and vacation dialog
_EX = [("galing", "good, skillful", "Ang galing-galing ng manlalaro!", "How very good the player is!"), ("tapang", "brave", "Ang tapang-tapang ng coach!", "How very brave the coach is!"), ("lakas", "strong", "Ang lakas-lakas ng boksingero!", "How very strong the boxer is!"), ("liksi", "agile, quick", "Ang liksi-liksi ng manlalangoy!", "How very agile the swimmer is!"), ("sakit", "painful", "Ang sakit-sakit ng kalamnan ko sa karate!", "How very painful my muscles are from karate!"), ("layo", "far", "Ang layo-layo ng basketball court!", "How very far the basketball court is!"), ("sipag", "diligent, hardworking", "Ang sipag-sipag ng basketbolista!", "How very hardworking the basketball player is!"), ("hirap", "difficult", "Ang hirap-hirap tumakbo!", "How very difficult it is to run!")]
