        + [M("What is arnis?", "The national sport and martial art of the Philippines", ["A kind of boxing glove", "A swimming style", "A card game"], "arnis."), M("What are other names for arnis?", "eskrima and kali", ["karate and boksing", "judo and sipa", "billiards and darts"], "eskrima, kali."), M("What does panganay ko mean?", "my oldest child", ["my youngest child", "my cousin", "my friend"], "panganay."), M("What does sumubok mean?", "tried", ["won", "lost", "quit"], "sumubok."), M("What does nag-enjoy mean?", "enjoyed", ["suffered", "worked", "slept"], "nag-enjoy."), M("What does sobrang nag-enjoy mean?", "enjoyed very much", ["did not enjoy", "enjoyed a little", "will enjoy"], "sobra."), M("What does ang sipag-sipag mean literally?", "how very industrious", ["how very painful", "how very far", "how very strong"], "sipag.")]
        + [F("Ang ___-galing ng manlalaro! (good)", "galing", ["tapang", "lakas"], "galing-galing."), F("Ang tapang-___ ng coach! (brave)", "tapang", ["lakas", "liksi"], "tapang-tapang."), F("Ang layo-___ ng basketball court! (far)", "layo", ["sipag", "sakit"], "layo-layo."), F("Ang sipag-___ ng basketbolista! (hardworking)", "sipag", ["hirap", "liksi"], "sipag-sipag."), F("Ang hirap-___ tumakbo! (difficult)", "hirap", ["sakit", "layo"], "hirap-hirap."), F("Nag-___ kami. (did wakeboarding)", "wakeboarding", ["arnis", "enjoy"], "nag-wakeboarding."), F("Nagbakasyon ako sa ’Pinas kasama ng dalawang ___ ko. (children)", "anak", ["asawa", "bakasyon"], "anak.")]
