        + [M("What is a manlalangoy?", "a swimmer", ["a player", "a boxer", "a coach"], "manlalangoy."), M("What is a manlalaro?", "a player", ["a swimmer", "a runner", "a member"], "manlalaro."), M("Which words are Spanish cognates?", "miyembro, benepisyo, beses, libre", ["madali, malakas, sapat", "katawan, tulog, palagi", "paano, dapat, marami"], "cognates."), M("What does Gaano kadalas? ask?", "How often?", ["How much?", "How far?", "How long?"], "kadalas."), M("What does sa simula mean?", "at the start", ["in the end", "all the time", "never"], "sa simula."), M("What does puwede nang isang beses isang linggo mean?", "once a week is already fine", ["every day is required", "once a year is enough", "never is fine"], "isang beses isang linggo.")]
